/**
 * Closed set of serialisations of one modelo calculation report.
 *
 * Attributes: CSV: The report's rows as a delimited table with fixed columns,
 * above a commented preamble carrying the report's header facts. Machine
 * readable, and the format a reviewer diffs or loads into a sheet. PDF: The
 * calculation summary: a tagged, archival page rendering of the report for a
 * person to read, carrying the report's canonical bytes, its CSV and a signed
 * integrity statement as embedded files. Needs the optional `pdf` extra to
 * write, and nothing optional to verify.
 */
export type CalculationReportDocumentFormat = "csv" | "pdf";

/**
 * Complete calculation-report receipt without report contents or taxpayer
 * identity.
 */
export type ModeloCalculationReportPublicReceipt = {
  calculation_revision_id: CalculationRevisionId;
  work_unit_id: WorkUnitId;
  verification_report_id: string | null;
  filing_record_id: FilingRecordId | null;
  modelo: string;
  filing_year: number;
  period: PublicPeriod;
  document_format: CalculationReportDocumentFormat;
  report_language: OutputLanguage;
  output_path: string;
  byte_size: number;
  file_sha256: ContentDigest;
  report_sha256: ContentDigest;
  row_count: number;
  software_identity_grade: AeatSoftwareIdentityGrade | null;
  local_calculation_notice: string;
  signing_key_fingerprint: ContentDigest | null;
};

/**
 * What one export's receipt says about whether every required casilla reached
 * the file.
 *
 * The export service states completeness only as a warning: it flags a fixed-
 * width filing file whose revision declares no completeness manifest, because
 * the structural-parity check could not run. Its silence is not a
 * verification, so it keeps its own member rather than reading as verified.
 *
 * Attributes: UNVERIFIED: The receipt flags the filing file as not
 * completeness-verified. NOT_FLAGGED: The filing file's receipt raises no
 * completeness warning. NOT_ASSESSED: A calculation report, which makes no
 * completeness statement.
 */
export type ModeloExportCompleteness =
  "unverified" | "not_flagged" | "not_assessed";

/**
 * One disclosed limitation of the exported calculation, as its verification
 * worded it.
 */
export type ModeloExportDisclosedLimitation = {
  message_locale_key: string;
  casilla_id: CasillaId | null;
  words: string;
};

/**
 * The disclosed limitations an export carries, with the sentence that
 * introduces them.
 */
export type ModeloExportDisclosure = {
  lead_words: string;
  limitations: ModeloExportDisclosedLimitation[];
};

/**
 * What one exported artefact is worth as evidence, in the export service's own
 * terms.
 *
 * Neither artefact is official AEAT evidence; the two members keep apart the
 * filing file an operator may present and the calculation record that can
 * never be presented, because the remedy an operator reads differs.
 *
 * Attributes: LOCAL_EXPORT_NOT_OFFICIAL_AEAT_FILING_EVIDENCE: The filing
 * file's own status token. Official evidence comes from AEAT only after
 * filing. LOCAL_CALCULATION_REPORT_NOT_OFFICIAL_AEAT_FILING_EVIDENCE: A
 * calculation report, whose receipt always carries the local-calculation
 * notice saying it is not official AEAT filing evidence.
 */
export type ModeloExportEvidenceStatus =
  | "local_export_not_official_aeat_filing_evidence"
  | "local_calculation_report_not_official_aeat_filing_evidence";

/**
 * Evidence that one export happened and what it could establish, without the
 * exported material.
 *
 * Custody of the artefact is the operator's from the moment it lands: this
 * result names the file and fingerprints it so a later reader can prove which
 * bytes were produced, and carries none of them. It also carries the three
 * facts an operator needs before relying on the file -- its evidence status,
 * its completeness and the grade of the software identity in its header -- so
 * an incomplete or development-grade export is stated, never implied.
 *
 * Each export carries its service's complete receipt so CLI and TUI can render
 * the canonical publication facts through the runtime.
 */
export type ModeloExportPublicResultV3 = {
  result_version: number;
  calculation_revision_id: string;
  artefact: ModeloExportArtefact;
  export_format: string;
  output_path: string;
  byte_size: number;
  file_sha256: ContentDigest;
  software_identity_grade: AeatSoftwareIdentityGrade | null;
  evidence_status: ModeloExportEvidenceStatus;
  completeness: ModeloExportCompleteness;
  fichero_boe: ModeloFicheroBoePublicReceipt | null;
  calculation_report: ModeloCalculationReportPublicReceipt | null;
  handoff_required: boolean;
  disclosure: ModeloExportDisclosure | null;
};

/**
 * The revision to export, where the operator wants the artefact, and the
 * elections that shape it.
 *
 * The path is the operator's chosen destination, journalled because it is a
 * location rather than content. The exported bytes never enter the request or
 * the result.
 *
 * The refund, payment and prior-domiciliation elections are the declaration-
 * shaping choices the command line also accepts, with the same neutral
 * defaults, so one revision exports as the same declaration type from either
 * surface. The instalment election defaults to paying at once, as the command
 * line exports.
 *
 * `actor` is recorded as sent for a person's session. An automation's session
 * is recorded under its own session label, whatever the request carries.
 */
export type ModeloExportRequest = {
  calculation_revision_id: string;
  output_path: string;
  refund_election?: RefundElection;
  payment_election?: PaymentElection;
  instalment_election?: PaymentInstalmentElection;
  prior_domiciliation_election?: PriorDomiciliationElection;
  charge_account_id?: string | null;
  refund_account_id?: string | null;
  replace_existing?: boolean;
  artefact?: ModeloExportArtefact;
  report_language?: OutputLanguage;
  actor: string;
};

/**
 * Whether a positive result is paid at once or in two instalments, and how the
 * second is paid.
 */
export type PaymentInstalmentElection =
  "single" | "two_instalments_second_debited" | "two_instalments_second_paid";
